WITH filtered_orders AS (SELECT *, CONCAT(channel, ' ', status) AS channel_status FROM orders WHERE NOT ((amount BETWEEN 1200 AND 1290 AND channel NOT IN ('web', 'store')) OR customer_id = 18)), orders_stats AS (SELECT QUARTER(order_date) AS order_quarter, channel, ROUND(STDDEV(discount), 2) AS stddev_discount, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list FROM filtered_orders GROUP BY QUARTER(order_date), channel) SELECT order_quarter, channel, stddev_discount, channel_list FROM orders_stats ORDER BY stddev_discount DESC, channel DESC;
